@layer components {
  :where([data-control-family="table"][data-slot="root"]) {
    --table-background: transparent;
    --table-foreground: var(--foreground);
    --table-border-color: var(--border);
    --table-footer-background: oklch(from var(--foreground) l c h / 0.03);
    --table-header-foreground: var(--muted-foreground);
    --table-row-hover-background: oklch(from var(--foreground) l c h / 0.03);
    --table-row-selected-background: oklch(from var(--foreground) l c h / 0.05);
    background: var(--table-background);
    color: var(--table-foreground);
  }

  :where([data-control-family="table"][data-slot="header"] [data-slot="row"]) {
    border-bottom-color: var(--table-border-color);
  }

  :where([data-control-family="table"][data-slot="footer"]) {
    border-top-color: var(--table-border-color);
    background: var(--table-footer-background);
  }

  :where([data-control-family="table"][data-slot="row"]) {
    border-bottom-color: var(--table-border-color);
    transition: background-color var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="table"][data-slot="row"]:is([data-interactive], [tabindex], [role="button"], :has(a, button, [role="checkbox"])):hover) {
    background: var(--table-row-hover-background);
  }

  :where([data-control-family="table"][data-slot="row"][data-state="selected"]) {
    background: var(--table-row-selected-background);
  }

  :where([data-control-family="table"][data-slot="head"]) {
    color: var(--table-header-foreground);
  }

  :where([data-control-family="table"][data-slot="caption"]) {
    color: var(--muted-foreground);
  }

  :where([data-control-family="table"][data-slot="caption"]) {
    font-size: var(--text-body);
  }

  :where([data-control-family="table"][data-slot="head"]) {
    --_table-head-text-align: left;
    text-align: var(--_table-head-text-align);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="table"][data-slot="row"]) {
    border-bottom-style: solid;
    border-bottom-width: 1px;
  }

  :where([data-control-family="table"][data-slot="footer"]) {
    border-top-style: solid;
    border-top-width: 1px;
    font-weight: var(--font-weight-medium);
    --__table-footer-tr-bottom-border-style: solid;
    --__table-footer-tr-bottom-border-width: 0px;
  }

  :where([data-control-family="table"][data-slot="footer"] > tr:last-child) {
    border-bottom-style: var(--__table-footer-tr-bottom-border-style);
    border-bottom-width: var(--__table-footer-tr-bottom-border-width);
  }

  :where([data-control-family="table"][data-slot="body"]) {
    --__table-body-tr-border-style: solid;
    --__table-body-tr-border-width: 0px;
  }

  :where([data-control-family="table"][data-slot="body"] tr:last-child) {
    border-style: var(--__table-body-tr-border-style);
    border-width: var(--__table-body-tr-border-width);
  }

  :where([data-control-family="table"][data-slot="header"]) {
    --__table-header-tr-bottom-border-style: solid;
    --__table-header-tr-bottom-border-width: 1px;
  }

  :where([data-control-family="table"][data-slot="header"] tr) {
    border-bottom-style: var(--__table-header-tr-bottom-border-style);
    border-bottom-width: var(--__table-header-tr-bottom-border-width);
  }

  :where([data-control-family="table"][data-slot="root"]) {
    border-collapse: collapse;
    font-size: var(--text-body);
  }
}

@property --table-background {
  syntax: "*";
  inherits: true;
  initial-value: transparent;
}

@property --table-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --table-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --table-row-hover-background {
  syntax: "*";
  inherits: true;
  initial-value: transparent;
}

@property --table-row-selected-background {
  syntax: "*";
  inherits: true;
  initial-value: transparent;
}

@property --table-header-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --table-footer-background {
  syntax: "*";
  inherits: true;
  initial-value: transparent;
}

import type {
  TableBodyProps,
  TableCaptionProps,
  TableCellProps,
  TableFooterProps,
  TableHeaderProps,
  TableHeadProps,
  TableProps,
  TableRowProps,
} from "@/components/control-ui/contracts";
import { cn } from "@/components/control-ui/lib/cn";

// wrapped in overflow-x-auto so wide tables scroll instead of blowing out layout
export function Table({ className, ...props }: TableProps) {
  return (
    <div data-control-ui="table" data-control-family="table" data-slot="container" className="relative w-full overflow-x-auto">
      <table
        data-control-ui="table"
        data-control-family="table"
        data-slot="root"
        className={cn("w-full caption-bottom", className)}
        {...props}
      />
    </div>
  );
}

export function TableHeader({ className, ...props }: TableHeaderProps) {
  return <thead data-control-ui="table" data-control-family="table" data-slot="header" className={className} {...props} />;
}

export function TableBody({ className, ...props }: TableBodyProps) {
  return <tbody data-control-ui="table" data-control-family="table" data-slot="body" className={className} {...props} />;
}

export function TableFooter({ className, ...props }: TableFooterProps) {
  return <tfoot data-control-ui="table" data-control-family="table" data-slot="footer" className={className} {...props} />;
}

export function TableRow({ className, ...props }: TableRowProps) {
  return <tr data-control-ui="table" data-control-family="table" data-slot="row" className={className} {...props} />;
}

export function TableHead({ className, ...props }: TableHeadProps) {
  return (
    <th
      data-control-ui="table"
      data-control-family="table"
      data-slot="head"
      className={cn("h-10 whitespace-nowrap px-2 align-middle [&:has([role=checkbox])]:pr-0", className)}
      {...props}
    />
  );
}

export function TableCell({ className, ...props }: TableCellProps) {
  return (
    <td
      data-control-ui="table"
      data-control-family="table"
      data-slot="cell"
      className={cn("whitespace-nowrap p-2 align-middle [&:has([role=checkbox])]:pr-0", className)}
      {...props}
    />
  );
}

export function TableCaption({ className, ...props }: TableCaptionProps) {
  return <caption data-control-ui="table" data-control-family="table" data-slot="caption" className={cn("mt-4", className)} {...props} />;
}
